import{_ as e,c as o,o as a,aN as r}from"./chunks/framework.wz1796_d.js";const g=JSON.parse('{"title":"加群","description":"加群","frontmatter":{"title":"加群","description":"加群"},"headers":[],"relativePath":"info/jq.md","filePath":"info/jq.md"}'),l={name:"info/jq.md"};function s(n,t,c,i,d,p){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="加群方式" tabindex="-1">加群方式 <a class="header-anchor" href="#加群方式" aria-label="Permalink to &quot;加群方式&quot;">​</a></h1><h2 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">注意</p><p>本工具全自动一键ROOT功能 仅支持 <strong>已解 BL 锁的小米、红米</strong> 系列机型</p><p>并且 <strong>仅支持</strong> 安卓9及以上的 <strong>官方系统</strong></p><p>非官方系统则无法正常使用，低于安卓9使用可能会造成 <strong>无法开机</strong></p><p>全自动一键ROOT <strong>不支持</strong> 红魔、黑鲨和其他品牌设备</p><p>由于验证文件为定向分发资源，分发后无法收回</p><p>若因赞助后无法使用 <strong>全自动一键ROOT</strong> 功能，不予退款，敬请知悉</p></div><p>加入官方工具群是需要<code>赞助15元</code>才可进群，如果你手动退出后重新申请需要重新赞助，敬请知悉！</p><h1 id="赞助方式有两种" tabindex="-1">赞助方式有两种 <a class="header-anchor" href="#赞助方式有两种" aria-label="Permalink to &quot;赞助方式有两种&quot;">​</a></h1><ol><li>通过「爱发电」平台赞助，凭「爱发电」平台私信的<code>入群密码</code>申请入群</li><li>通过「直接扫码」赞助，凭赞助 <code>平台</code> + <code>订单号后6位</code>申请入群</li></ol><blockquote><p>上述两种方式均需人工审核，无法保证进群即时性</p><p>通过「爱发电」方式赞助后可立即获取验证文件下载链接，入群审核期间可先行使用工具</p><p>若仍选择「直接扫码」方式，请耐心等待后续处理</p></blockquote><h2 id="方式1-爱发电赞助" tabindex="-1">方式1：爱发电赞助 <a class="header-anchor" href="#方式1-爱发电赞助" aria-label="Permalink to &quot;方式1：爱发电赞助&quot;">​</a></h2><p>赞助方案：<a href="https://ifdian.net/item/bc14b8acf8fc11f0a7195254001e7c00" target="_blank" rel="noreferrer">点击访问</a></p><blockquote><p>如上方链接无法访问请尝试访问 <a href="https://ifdian.net/a/dishuo" target="_blank" rel="noreferrer">爱发电主页</a>，下拉找到<code>加群方案</code></p></blockquote><p>请在赞助时在平台留下你的QQ号用作入群审核，赞助后完成后请查看爱发电的 <a href="https://ifdian.net/message" target="_blank" rel="noreferrer">私信</a>，系统会自动发送<code>群号</code>和<code>入群密码</code>，请凭<code>入群密码</code>申请进群。</p><div class="danger custom-block"><p class="custom-block-title">注意</p><p>如果你 <strong>着急</strong> 获取验证文件使用工具但又想进群，建议使用上方<code>爱发电</code>的赞助方式</p><p>赞助后平台会自动发送<code>验证文件</code>和<code>入群密码</code>，入群审核期间可先行使用工具</p></div><h2 id="方式2-直接扫码赞助" tabindex="-1">方式2：直接扫码赞助 <a class="header-anchor" href="#方式2-直接扫码赞助" aria-label="Permalink to &quot;方式2：直接扫码赞助&quot;">​</a></h2><blockquote><p>申请时请填写 <strong>平台</strong> + <strong>订单号后6位</strong>，例如 <code>微信123456</code></p><p>后台都有记录，乱填将 <strong>永久禁止申请入群</strong></p><p>微信无法通过相册扫描时可以用其他设备展示此码再扫</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:center;">微信</th><th style="text-align:center;">支付宝</th></tr></thead><tbody><tr><td style="text-align:center;"><img src="https://pic.dishuo183.top/images/root/2026/03/14/236425238.png" alt="WeChat QRcode" width="300"></td><td style="text-align:center;"><img src="https://pic.dishuo183.top/images/root/2026/03/14/3118944190.png" alt="Alipay QRcode" width="300"></td></tr></tbody></table><h3 id="当前官方群" tabindex="-1">当前官方群 <a class="header-anchor" href="#当前官方群" aria-label="Permalink to &quot;当前官方群&quot;">​</a></h3><ul><li>官方①群：688965779 [推荐]</li><li>官方②群：752669939 [即将满]</li><li>官方③群：<s>542093757</s> [已满]</li></ul><blockquote><p>推荐申请官方①群，如乱填验证信息将 <strong>永久禁止申请入群</strong></p></blockquote><div class="warning custom-block"><p class="custom-block-title">注意</p><p>如果使用直接扫码赞助，凭赞助 <strong>平台</strong> + <strong>订单号后6位</strong>申请入群，例如 <code>微信123456</code></p><p>此方案为人工审核，一般12小时之内。长时间未同意可加QQ群 <a href="https://qm.qq.com/q/MaDMmc7EQ4" target="_blank" rel="noreferrer">385475461</a> 私聊群主询问</p><p><strong>如着急使用工具但又想进群，推荐上方的爱发电入群方案！</strong></p></div><h2 id="其它项目" tabindex="-1">其它项目 <a class="header-anchor" href="#其它项目" aria-label="Permalink to &quot;其它项目&quot;">​</a></h2><ul><li>如果你需要额外远程服务，可加作者QQ <a href="https://qm.qq.com/q/zP6sh9CFBC" target="_blank" rel="noreferrer">1871549721</a>，验证信息备注【需要远程服务】</li><li>如果你需要日常刷机指导等服务，可查看爱发电的 <a href="https://ifdian.net/item/b86f043cf90611f09b4c52540025c377" target="_blank" rel="noreferrer">刷机指导</a> 方案</li><li>如果你只需要获取验证文件，可查看爱发电的 <a href="https://ifdian.net/item/e3d9d834f8f911f086de52540025c377" target="_blank" rel="noreferrer">工具验证文件</a> 方案</li></ul><div class="tip custom-block"><p class="custom-block-title">提示</p><p>赞助获取验证文件后，请记得收藏下载链接，验证文件会不定期更新，更新后需重新下载！</p></div>',22)])])}const b=e(l,[["render",s]]);export{g as __pageData,b as default};
